  split; [lia|]. split; [lia|]. split; [lia|]. split; [lia|]. split; [clear - X3 H1 H2 G4; destruct X3; lia|].
  split; [clear - X4 H1 H2 G4; destruct X4; lia|]. split; [lia | exact I].
