Lemma sl_static : forall (m : mem), munch W_T m2 m -> wmono asegs m2 m ->
  thread_cells TCX T m /\ m2s_cells m /\ ps_cells m /\ setshadow_cells m
  /\ rw_cells asegs m g_GOT_asan_flags [C8 (Z_to_bv 64 g_asan_flags)] /\ rw_cells asegs m (g_asan_flags + 44) [C4 (Z_to_bv 64 4096)]
  /\ rw_cells asegs m (g_asan_flags + 52) [C4 (Z_to_bv 64 190)] /\ rw_cells asegs m (g_asan_flags + 85) [C1 (Z_to_bv 8 1)]
  /\ rw_cells asegs m (tpA + 16) [C4 (Z_to_bv 64 0)] /\ rw_cells asegs m 0x10b7b8 [C8 (Z_to_bv 64 16)]
  /\ rw_cells asegs m g_MFHooks [C8 (Z_to_bv 64 0)] /\ rw_cells asegs m g_can_poison_memory [C1 (Z_to_bv 8 1)]
  /\ rw_cells asegs m (TCX + 8) [C4 (Z_to_bv 64 0)] /\ rw_cells asegs m T [C8 (Z_to_bv 64 TCX)]
  /\ rw_cells asegs m i_spacebeg [C8 (Z_to_bv 64 SB)] /\ sec_page m.
Proof using Hn HA HG LOW LOR SPT MU1 WM1. clear - Hn HA HG LOW LOR SPT MU1 WM1.
  intros m MU0 WM0. pose proof (sl_mS m MU0) as MU. pose proof (wmono_trans asegs _ _ _ WM1 WM0) as WM. clear MU0 WM0.
  pose proof (ART_consts Σ mA HA) as ((SBC0 & _) & _ & ((T1 & T2 & T3 & T4) & T5) & (M1 & M2 & M3) & (P1 & _ & (S1 & S2) & P3 & P4) & _ & _
    & (X1 & X2 & X3 & X4 & X5 & X6 & X7 & X8 & X9 & X10 & X11 & X12 & X13 & X14 & X15 & X16 & X17 & X18 & X19 & X20 & X21 & X22 & X23 & X24
       & X25 & X26 & X27 & X28 & X29 & X30 & X31 & _ & X33 & _)).
  pose proof (ART_sec Σ mA HA) as (_ & _ & _ & PG & _).
  pose proof sl_geo as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & G11 & G12 & G13 & G14 & _).
  assert (SBC : rw_cells asegs mA i_spacebeg [C8 (Z_to_bv 64 SB)]) by exact (rw_cells_app_l mA _ [C8 (Z_to_bv 64 SB)] _ SBC0).
  assert (M' : m2s_cells m) by (split; [sw_lit M1 MU WM | split; [sw_lit M2 MU WM | sw_lit M3 MU WM]]).
  assert (SS' : setshadow_cells m) by (split; [sw_lit S1 MU WM | sw_lit S2 MU WM]).
  split.
  { split; [split; [sw_lit T1 MU WM | split; [sw_lit T2 MU WM | split; [sw_lit T3 MU WM | sw_lit T4 MU WM]]]|].
    apply (rw_cells_transport asegs _ _ _ _ _ T5 MU WM). cbn [cells_size csize Nat.add]. apply sw_TCX; lia. }
  split; [exact M'|]. split; [split; [sw_lit P1 MU WM | split; [exact M' | split; [exact SS' | split; [sw_lit P3 MU WM | sw_lit P4 MU WM]]]]|].
  split; [exact SS'|].
  split; [sw_lit X23 MU WM|]. split; [sw_lit X24 MU WM|]. split; [sw_lit X25 MU WM|]. split; [sw_lit X26 MU WM|].
  split; [unfold tpA; sw_lit X27 MU WM|]. split; [sw_lit X28 MU WM|]. split; [unfold g_MFHooks; sw_lit X29 MU WM|].
  split; [unfold g_can_poison_memory; sw_lit X30 MU WM|].
  split.
  { apply (rw_cells_transport asegs _ _ _ _ _ X31 MU WM). cbn [cells_size csize Nat.add]. apply sw_TCX; lia. }
  split; [apply (rw_cells_transport asegs _ _ _ _ _ X33 MU WM); cbn [cells_size csize Nat.add]; apply sw_T; lia|].
  split; [sw_lit SBC MU WM|]. unfold sec_page in *. sw_lit PG MU WM.
Qed.

