Lemma sl_munch_into : forall W (m3 m4 : mem), munch W_T m2 m3 -> munch W m3 m4 -> sub_fp W W_T -> munch W_T m2 m4.
Proof using Σ m2 B n P. intros W m3 m4 MU MU' Hs. exact (munch_into _ _ m2 m3 m4 MU MU' Hs). Qed.

