Lemma sl_p3b : forall (m6 : mem) (t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 ra0 s0v s6v s9v s3v : word)
    (h0 : list byte) (b1 : Z) (ctx : word),
  munch W_T m2 m6 -> wmono asegs m2 m6 -> mem_inv asegs m6 -> stk asegs m6 lo (B + -144) ->
  af_cells B s0A s1A s2A s3A s4A s5A s6A s7A s8A s9A s10A s11A m6 j0 -> 0 <= b1 < 256 -> b1 mod 4 = 1 ->
  rw_cells asegs m6 (AB + 2048 + -16) [CB 1 h0; C1 (Z_to_bv 8 b1); C2 (Z_to_bv 64 0); C4 (Z_to_bv 64 n); C8 ctx] ->
  bytes_at asegs m6 (shad (AB + 2048)) (ushadow n) -> bytes_at asegs m6 (shad AB) (farun (2048 / 8)) ->
  bytes_at asegs m6 (shad (AB + 2048 + ru8 n)) (farun ((S - 2048 - ru8 n) / 8)) ->
  depot_rep (fst (depot_put D tr)) BK DNB SSB m6 ->
  evt asegs sl_post (MS (mkR ra0 (Z_to_bv 64 (B + -144)) gp (Z_to_bv 64 tpA) t0 t1 t2 s0v (Z_to_bv 64 n) a0 a1 a2 a3 a4 a5 a6 a7
                             (Z_to_bv 64 AB) s3v (Z_to_bv 64 (AB + rz_size n)) (Z_to_bv 64 (AB + rz_size n + -16)) s6v
                             (Z_to_bv 64 B) (Z_to_bv 64 0) s9v (Z_to_bv 64 T) (Z_to_bv 64 1) t3 t4 t5 t6)
